<template><view class="billing"><text class="heading">购买额度 / 开通会员</text><text v-if="!enabled" class="notice">购买功能暂未开放，可查看已有权益与订单。</text><text v-if="error" class="error">{{error}}</text><button size="mini" @click="refresh">刷新权益与订单</button><view v-if="account" class="card"><text>剩余咨询 {{account.remainingChat}} 次 · 审查 {{account.remainingReview}} 次</text><text>{{account.memberActive ? '会员有效至 '+account.memberUntil : '暂无有效会员'}}</text></view>
<view v-for="p in plans" :key="p.code" class="card"><text class="heading">{{p.name}} · ¥{{Number(p.price).toFixed(2)}}</text><text>咨询 {{p.chatCredits}} 次，审查 {{p.reviewCredits}} 次；次数有效 {{p.validDays}} 天<text v-if="p.memberDays">，会员 {{p.memberDays}} 天</text></text><button :disabled="!enabled||busy" :loading="busy" @click="buy(p)">购买</button></view><text v-if="!plans.length" class="notice">暂无可购买套餐</text>
<view v-if="selected" class="card"><text class="heading">{{selected.planName}} · {{statusLabel(selected.status)}}</text><text>订单 {{selected.orderNo}}</text><text>¥{{Number(selected.amount).toFixed(2)}}</text><template v-if="selected.status==='PENDING'"><uqrcode v-if="selected.payUrl" canvas-id="billing-code" :value="selected.payUrl" :size="220" :options="{margin:10}"/><text>使用支付宝扫码完成付款，支付结果以服务器核实为准；关闭页面不会取消订单。</text><text>支付期限：{{selected.expiresAt}}</text><button :disabled="busy||!enabled" @click="check">我已支付，查询结果</button><button :disabled="busy||!enabled" @click="cancel">取消未付订单</button><button v-if="selected.payUrl" size="mini" @click="copyLink">复制支付链接</button></template><text v-else-if="selected.status==='PAID'">支付成功，权益已刷新。</text></view>
<text class="heading">我的订单</text><view v-for="o in orders" :key="o.orderNo" class="card" @click="open(o)"><text>{{o.planName}} · ¥{{Number(o.amount).toFixed(2)}} · {{statusLabel(o.status)}}</text><text>{{o.createdAt}}</text><text>查看详情 ›</text></view><text v-if="!orders.length" class="notice">暂无订单</text><view><button size="mini" :disabled="page===1" @click="changePage(-1)">上一页</button><text> 第 {{page}} 页 </text><button size="mini" :disabled="orders.length<20" @click="changePage(1)">下一页</button></view></view></template>
<script>
import Uqrcode from '@/uni_modules/Sansnn-uQRCode/components/uqrcode/uqrcode.vue';
export default{components:{Uqrcode},data(){return{enabled:false,plans:[],orders:[],account:null,selected:null,error:'',busy:false,page:1};},onShow(){const nextToken=uni.getStorageSync('token');if(this._token&&this._token!==nextToken){this._keys={};this.selected=null;this.account=null;this.orders=[];this.plans=[];}this._token=nextToken;this._closed=false;this._keys=this._keys||{};if(!this._token){uni.navigateTo({url:'/pages/h5/login'});return;}this.refresh();},onHide(){this.stop();},onUnload(){this._closed=true;this.stop();},methods:{
 statusLabel(status){return{PENDING:'待支付',PAID:'已支付',CLOSED:'已关闭',REFUNDED:'已退款'}[status]||'待核实';},current(token){return !this._closed&&token===uni.getStorageSync('token');},stop(){if(this._timer)clearTimeout(this._timer);this._timer=null;},
 async api(path,method='GET',data={}){const token=this._token;const r=await this.$request('/lawyer/billing'+path,method,data,{'content-type':'application/json'});if(!this.current(token))throw new Error('登录用户已变化，请返回我的页面');if(Number(r.code)!==200)throw new Error(r.msg||'操作失败，请重试');return r.data;},
 async refresh(){this.error='';try{const [catalog,account,orders]=await Promise.all([this.api('/plans'),this.api('/account'),this.api('/orders','GET',{page:this.page})]);this.enabled=catalog.purchasingEnabled;this.plans=catalog.plans;this.account=account;this.orders=orders;}catch(e){this.error=e.message;}},
 poll(){this.stop();if(!this.enabled||!this.selected||this.selected.status!=='PENDING'||(this._attempts||0)>=180)return;this._attempts=(this._attempts||0)+1;this._timer=setTimeout(()=>this.check(),5000);},
 async buy(plan){if(this.busy||!this.enabled)return;this.busy=true;this.stop();this.error='';try{const key=this._keys[plan.code]||(this._keys[plan.code]='mobile_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2)+'_'+Math.random().toString(36).slice(2));this.selected=await this.api('/orders','POST',{planCode:plan.code,idempotencyKey:key});this._attempts=0;await this.refresh();}catch(e){this.error=e.message;}finally{this.busy=false;this.poll();}},
 async check(){if(this.busy||!this.selected)return;try{this.selected=await this.api('/orders/'+encodeURIComponent(this.selected.orderNo),'GET',{refresh:true});if(this.selected.status==='PENDING')this.poll();else{this._keys={};this.stop();await this.refresh();}}catch(e){this.stop();this.error=e.message;}},
 async cancel(){if(this.busy||!this.selected)return;this.busy=true;this.stop();try{this.selected=await this.api('/orders/'+encodeURIComponent(this.selected.orderNo)+'/close','POST');if(this.selected.status!=='PENDING')this._keys={};await this.refresh();}catch(e){this.error=e.message;}finally{this.busy=false;}},
 open(order){this.selected=order;this._attempts=0;if(this.enabled)this.check();},changePage(delta){this.page=Math.max(1,this.page+delta);this.refresh();},copyLink(){if(this.selected&&this.selected.payUrl)uni.setClipboardData({data:this.selected.payUrl});}
}};
</script><style scoped>.billing{padding:32rpx;background:var(--brand-background);min-height:100vh}.heading{display:block;font-size:20px;font-weight:600;margin:20rpx 0}.card{background:#fff;border:1px solid var(--brand-border);border-radius:20rpx;margin:24rpx 0;padding:24rpx;overflow-wrap:anywhere}.card text{display:block;margin:16rpx 0;font-size:16px;line-height:1.8}.notice,.error{display:block;font-size:16px;line-height:1.8;margin:20rpx 0}.error{color:var(--brand-danger)}button{margin:16rpx 0}</style>
